	/*
     * @param	event CreateReviewEvent
     */
    @EventHandler( payloadType=CreateReviewEvent.class )
    public void handle( CreateReviewEvent event) {
	    LOGGER.info("handling CreateReviewEvent - " + event );
	    Review entity = new Review();
            entity.setReviewId( event.getReviewId() );
            entity.setRating( event.getRating() );
            entity.setTitle( event.getTitle() );
            entity.setContent( event.getContent() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllReview( entity );
    }

    /*
     * @param	event UpdateReviewEvent
     */
    @EventHandler( payloadType=UpdateReviewEvent.class )
    public void handle( UpdateReviewEvent event) {
    	LOGGER.info("handling UpdateReviewEvent - " + event );
    	
	    Review entity = new Review();
            entity.setReviewId( event.getReviewId() );
            entity.setRating( event.getRating() );
            entity.setTitle( event.getTitle() );
            entity.setContent( event.getContent() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setProduct( event.getProduct() );
            entity.setCustomer( event.getCustomer() );
            entity.setOrder( event.getOrder() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindReview( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllReview( entity );        
    }
    
