    /**
     * Method to retrieve the Review via an ReviewPrimaryKey.
     * @param 	id Long
     * @return 	Review
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Review handle( FindReviewQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getReviewId() );
    }
    
    /**
     * Method to retrieve a collection of all Reviews
     *
     * @param	query	FindAllReviewQuery 
     * @return 	List<Review> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Review> handle( FindAllReviewQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindReview,
 * but only if the id matches
 *
 * @param		entity	Review
 */
	protected void emitFindReview( Review entity ) {
		LOGGER.info("handling emitFindReview" );
		
	    queryUpdateEmitter.emit(FindReviewQuery.class,
	                            query -> query.getFilter().getReviewId().equals(entity.getReviewId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllReview
	 * 
	 * @param		entity	Review
	 */
	protected void emitFindAllReview( Review entity ) {
		LOGGER.info("handling emitFindAllReview" );
		
	    queryUpdateEmitter.emit(FindAllReviewQuery.class,
	                            query -> true,
	                            entity);
	}

